(function(){
'use strict';
var DICT={"Main":"Основное","Vane home":"Главная Vane","Features":"Возможности","Networks":"Сети","Developers":"Разработчикам","Integrations":"Интеграции","Pricing":"Цены","Partners":"Партнёры","Log in":"Войти","Toggle menu":"Открыть меню","Publish everywhere. Schedule anything.":"Публикуйте везде. Планируйте что угодно.","Write, preview, publish and schedule across all your channels, with video, AI and an API built in.":"Пишите, смотрите превью, публикуйте и планируйте по всем каналам. Видео, ИИ и API уже внутри.","Get started":"Начать","Start free, no card required.":"Бесплатно, без карты.","Early Bird, per month. Unlimited channels and workspaces. Standard price is":"Early Bird, в месяц. Неограниченно каналов и рабочих пространств. Обычная цена —","Why Vane":"Почему Vane","No per-channel fee.":"Без платы за канал.","Unlimited channels and workspaces.":"Неограниченно каналов и рабочих пространств.","Edge-speed publishing.":"Публикация на скорости edge.","Posts leave on the minute.":"Посты уходят ровно в минуту.","AI and API included.":"ИИ и API включены.","From hashtags to a full REST gateway.":"От хештегов до полноценного REST-шлюза.","Live demo":"Живое демо","Write once. Preview everywhere.":"Пишите один раз. Превью везде.","Type or paste a post, pick your networks and see exactly how it lands on Telegram, Bluesky, Mastodon, Discord and Dev.to, limits included, before it ever goes out.":"Напишите или вставьте пост, выберите сети и увидите, как он ляжет в Telegram, Bluesky, Mastodon, Discord и Dev.to, с учётом лимитов, ещё до отправки.","Your post":"Ваш пост","Write or paste your post…":"Напишите или вставьте пост…","Publish to":"Куда публиковать","When":"Когда","Schedule post":"Запланировать пост","Simulated demo. Nothing is posted anywhere and your text never leaves this page.":"Демо-симуляция. Ничего никуда не публикуется, а ваш текст не покидает эту страницу.","Posting":"Публикации","Write once. Publish and schedule on your terms.":"Пишите один раз. Публикуйте и планируйте как удобно вам.","One draft goes to every channel you pick, at the time you choose. Afterwards you see what happened in each channel.":"Один черновик уходит во все выбранные каналы в нужное вам время. Потом вы видите, что произошло в каждом канале.","One draft, many channels.":"Один черновик — много каналов.","Telegram, Bluesky, Mastodon, Discord and Dev.to work today. More open as each network approves Vane.":"Telegram, Bluesky, Mastodon, Discord и Dev.to работают уже сейчас. Остальные откроются, когда сети одобрят Vane.","Preview before you send.":"Превью перед отправкой.","Each channel shows how the post will look and counts its own limit: Telegram 4,096, Mastodon 500, Bluesky 300. You get a warning before you go over.":"Каждый канал показывает, как будет выглядеть пост, и считает свой лимит: Telegram 4 096, Mastodon 500, Bluesky 300. Вы получите предупреждение до превышения.","Pick the moment.":"Выберите момент.","Any date and hour in your time zone, or one tap: in 1 hour, tomorrow at 9:00 or 18:00, or the hour you usually post. A seven-day strip shows how many posts are already planned each day.":"Любая дата и час в вашем часовом поясе или одно нажатие: через 1 час, завтра в 9:00 или 18:00, либо в час, когда вы обычно публикуете. Семидневная лента показывает, сколько постов уже запланировано на каждый день.","Clean text in one click.":"Чистый текст в один клик.","Tidy up removes stray spaces, hidden characters and tracking tags from links. Hashtag memory suggests tags you used before. Snippets drop in your signature.":"«Привести в порядок» убирает лишние пробелы, скрытые символы и трекинг-метки из ссылок. Память хештегов подсказывает теги, которые вы уже использовали. Сниппеты вставляют вашу подпись.","It goes out on the minute.":"Уходит ровно в минуту.","The publisher checks every minute. Temporary errors (network, Telegram busy) are retried up to five times. Permanent ones (bot removed, bad image) fail at once and say why. A post more than two hours late is not sent stale.":"Публикатор проверяет очередь каждую минуту. Временные ошибки (сеть, Telegram занят) повторяются до пяти раз. Постоянные (бот удалён, плохое изображение) сразу помечаются неудачей с причиной. Пост, опоздавший больше чем на два часа, не отправляется устаревшим.","Cancel, reuse, automate.":"Отменяйте, используйте повторно, автоматизируйте.","Cancel a scheduled post before it goes, or copy a sent post back into the editor. The same posting works from the REST API and Claude. Make, Zapier, Notion and Obsidian work today.":"Отмените запланированный пост до отправки или верните отправленный в редактор. Всё то же работает через REST API и Claude. Make, Zapier, Notion и Obsidian работают уже сейчас.","Vane Analytics":"Vane Analytics","See what every post actually achieved.":"Смотрите, чего на самом деле добился каждый пост.","The results of your posts and the growth of your audience in one place. Vane reads only the numbers of the posts it published for you. It never reads your feed, your messages or your follower lists.":"Результаты постов и рост аудитории в одном месте. Vane читает только цифры постов, которые сам опубликовал для вас. Он никогда не читает вашу ленту, сообщения и списки подписчиков.","Results per post.":"Результаты по постам.","Views, likes, replies and reposts for every post you sent through Vane. Numbers appear about an hour after publishing.":"Просмотры, лайки, ответы и репосты для каждого поста, отправленного через Vane. Цифры появляются примерно через час после публикации.","Networks today.":"Сети сегодня.","Results from Bluesky, Mastodon and Dev.to. Followers from Bluesky, Mastodon and Telegram. More are coming.":"Результаты из Bluesky, Mastodon и Dev.to. Подписчики из Bluesky, Mastodon и Telegram. Скоро будут и другие.","Find anything fast.":"Быстрый поиск.","Filter by network and period. Sort by newest, most reactions, likes, replies, reposts or views. Search the text.":"Фильтр по сети и периоду. Сортировка по новизне, реакциям, лайкам, ответам, репостам или просмотрам. Поиск по тексту.","Followers and what works.":"Подписчики и что работает.","Followers now and the change over the period. Pro adds a growth chart per network, a comparison of your networks and the best day and hour to publish.":"Подписчики сейчас и изменение за период. Pro добавляет график роста по каждой сети, сравнение сетей и лучший день и час для публикации.","Reports.":"Отчёты.","Pro exports CSV and sends a weekly report by email.":"Pro экспортирует CSV и присылает еженедельный отчёт по почте.","Telegram bot.":"Telegram-бот.","Ask for your numbers right in Telegram. Pro adds daily follower changes, alerts when a post takes off and digests.":"Спрашивайте свои цифры прямо в Telegram. Pro добавляет ежедневные изменения подписчиков, оповещения, когда пост «взлетает», и дайджесты.","Free":"Бесплатно","Pro add-on":"Дополнение Pro","History":"История","30 days":"30 дней","12 months":"12 месяцев","Posts list":"Список постов","10 latest":"10 последних","All, with search":"Все, с поиском","Results, reactions per day, best posts":"Результаты, реакции по дням, лучшие посты","Followers now and change":"Подписчики сейчас и изменение","Growth charts, compare networks, best time":"Графики роста, сравнение сетей, лучшее время","CSV export, weekly email":"Экспорт CSV, еженедельное письмо","Open Vane Analytics":"Открыть Vane Analytics","Vane Studio":"Vane Studio","Coming soon":"Скоро","Publish videos like you publish posts.":"Публикуйте видео так же, как посты.","Type a title, press publish and watch it land on your channel. Vane Studio runs Shorts, Reels, TikTok and long-form YouTube through the same simple flow. Try it on the iPad.":"Введите название, нажмите «Опубликовать» и смотрите, как видео появляется в вашем канале. Vane Studio ведёт Shorts, Reels, TikTok и длинные ролики YouTube через один простой процесс. Попробуйте на iPad.","Every video format.":"Все видеоформаты.","YouTube Shorts, TikTok and Instagram Reels, plus YouTube long-form with custom thumbnails, playlists and tags.":"YouTube Shorts, TikTok и Instagram Reels, а также длинные ролики YouTube с собственными обложками, плейлистами и тегами.","Uploads that survive bad Wi-Fi.":"Загрузка, которая переживёт плохой Wi-Fi.","Large files go up in resumable chunks through Cloudflare R2.":"Большие файлы загружаются возобновляемыми частями через Cloudflare R2.","AI for the boring parts.":"ИИ для рутины.","Hooks, scripts, descriptions, tags and timestamps.":"Хуки, сценарии, описания, теги и таймкоды.","Get notified":"Сообщить о запуске","a month, arriving after launch.":"в месяц, после запуска.","YouTube":"YouTube","Search":"Поиск","Your Channel":"Ваш канал","@yourchannel · 12.4K subscribers":"@yourchannel · 12,4 тыс. подписчиков","Subscribed":"Вы подписаны","New video":"Новое видео","0 / 3 uploads":"0 / 3 загрузок","Video title…":"Название видео…","Publish video":"Опубликовать видео","Reset demo":"Сбросить демо","Simulated demo. Nothing is uploaded anywhere, and the video you publish only exists on this page.":"Демо-симуляция. Ничего никуда не загружается, а опубликованное вами видео существует только на этой странице.","How Vane Studio works":"Как работает Vane Studio","A separate dashboard for video on the same account, with its own API keys and a free test mode. Four steps from file to published.":"Отдельная панель для видео в том же аккаунте, со своими API-ключами и бесплатным тестовым режимом. Четыре шага от файла до публикации.","1. Upload":"1. Загрузка","Drop the file. It goes up in parts, so a weak connection does not mean starting over. Videos stay in your private library.":"Бросьте файл. Он загружается частями, поэтому слабое соединение не заставит начинать заново. Видео хранятся в вашей приватной библиотеке.","2. Write":"2. Текст","The AI writer drafts a script (hook, body, call to action), titles, a description, tags and YouTube chapters with timecodes.":"ИИ-автор составляет сценарий (хук, основная часть, призыв к действию), названия, описание, теги и главы YouTube с таймкодами.","3. Publish":"3. Публикация","YouTube Shorts and long-form, TikTok and Instagram Reels. Each opens as the network approves Vane. The publishing queue is already built.":"YouTube Shorts и длинные ролики, TikTok и Instagram Reels. Каждая сеть открывается по мере одобрения Vane. Очередь публикации уже готова.","4. Announce":"4. Анонс","Share the new video in your Vane Post channels in one click. The text and the link are prefilled and fitted to each limit.":"Поделитесь новым видео в каналах Vane Post в один клик. Текст и ссылка уже подставлены и подогнаны под лимит каждой сети.","Publishing to YouTube, TikTok and Instagram needs approval from Google, TikTok and Meta. Studio goes live as each one clears.":"Для публикации в YouTube, TikTok и Instagram нужно одобрение Google, TikTok и Meta. Studio запускается по мере того, как каждая сеть его даёт.","Fewer knobs. Faster posts. A price that never moves.":"Меньше настроек. Быстрее посты. Цена, которая не меняется.","Most social tools charge for every channel you add. Vane charges one flat price, runs on the edge, and ships with AI and an API instead of upsells.":"Большинство соцсервисов берут плату за каждый добавленный канал. Vane берёт одну фиксированную цену, работает на edge и поставляется с ИИ и API вместо допродаж.","No per-channel fee":"Без платы за канал","Connect every account and workspace you own. One flat price, no meters on profiles and no surprise line items.":"Подключайте все свои аккаунты и рабочие пространства. Одна фиксированная цена, никаких счётчиков на профили и неожиданных строк в счёте.","1 min":"1 мин","Edge-speed publishing":"Публикация на скорости edge","A scheduler on Cloudflare’s edge wakes up every minute and ships whatever is due. No queue lag, no cold servers to wait for.":"Планировщик на edge Cloudflare просыпается каждую минуту и отправляет всё, что пора. Никаких задержек очереди и ожидания холодных серверов.","Many networks, one draft":"Много сетей — один черновик","Telegram, Bluesky, Mastodon, Discord and Dev.to from a single post, with more networks joining as they approve Vane.":"Telegram, Bluesky, Mastodon, Discord и Dev.to из одного поста, а другие сети подключаются по мере одобрения Vane.","Previews that know the limits":"Превью, которые знают лимиты","See the post as it will look on each network, with a warning before you cross its character limit.":"Смотрите, как пост будет выглядеть в каждой сети, с предупреждением до превышения лимита символов.","Telegram, done properly":"Telegram — как надо","Quick Connect proves the channel is yours with a one-time code. No bot token to copy.":"Quick Connect подтверждает, что канал ваш, одноразовым кодом. Токен бота копировать не нужно.","Drafts, snippets and history":"Черновики, сниппеты и история","Park unfinished posts, reuse your signature and hashtags, and copy any sent post back into the editor.":"Откладывайте недописанные посты, используйте подпись и хештеги повторно и возвращайте любой отправленный пост в редактор.","Media library on R2":"Медиатека на R2","Images and video live on Cloudflare R2, right next to the publisher that sends them.":"Изображения и видео хранятся в Cloudflare R2, рядом с публикатором, который их отправляет.","Delivery logs you can trust":"Журнал доставки, которому можно верить","Every attempt is recorded, so when something fails you know which channel and why.":"Каждая попытка записывается, поэтому при сбое вы знаете, какой канал и почему.","What’s inside":"Что внутри","Every module, in plain words.":"Каждый модуль — простыми словами.","Vane is a full home for your social media: write, preview, publish, schedule, see what worked and automate the rest. Here is each part and what it does.":"Vane — полноценный дом для ваших соцсетей: пишите, смотрите превью, публикуйте, планируйте, смотрите, что сработало, и автоматизируйте остальное. Вот каждая часть и что она делает.","Vane Post":"Vane Post","Run your channels":"Управляйте каналами","Everything for text and picture posts, from the first draft to the delivery report.":"Всё для текстовых и картиночных постов: от первого черновика до отчёта о доставке.","Create":"Создание","Composer":"Редактор","One draft for every network. Write it, attach pictures, tidy the text in one click (stray spaces, hidden characters, tracking tags in links), reuse your hashtags, then publish on the time you choose.":"Один черновик для всех сетей. Пишите, прикрепляйте картинки, наводите порядок в тексте одним кликом (лишние пробелы, скрытые символы, трекинг-метки в ссылках), используйте свои хештеги и публикуйте в выбранное время.","Live previews":"Живые превью","See the post the way each network will show it, with its own character counter and a warning before you go over the limit. No surprises after it is out.":"Смотрите пост так, как его покажет каждая сеть: со своим счётчиком символов и предупреждением до превышения лимита. Никаких сюрпризов после публикации.","Channels":"Каналы","Connect Telegram, Bluesky, Mastodon, Discord and Dev.to today. LinkedIn, Threads, Reddit and Facebook Pages open as each network approves Vane. No per-channel fee.":"Подключайте Telegram, Bluesky, Mastodon, Discord и Dev.to уже сейчас. LinkedIn, Threads, Reddit и страницы Facebook откроются по мере одобрения Vane. Без платы за канал.","Telegram Quick Connect":"Telegram Quick Connect","Add the Vane bot to your channel as an admin, post the one-time code, done. The code proves the channel is really yours, so nobody can attach a channel they do not control.":"Добавьте бота Vane админом в канал, отправьте одноразовый код — готово. Код подтверждает, что канал действительно ваш, поэтому никто не подключит канал, который не контролирует.","Track":"Контроль","Posts and delivery log":"Посты и журнал доставки","Upcoming and sent posts in one list, with the result for every channel. If something fails you see where and why. Reuse a finished post, or cancel a scheduled one.":"Предстоящие и отправленные посты в одном списке, с результатом по каждому каналу. Если что-то сломалось, вы видите где и почему. Используйте готовый пост повторно или отмените запланированный.","Insights":"Аналитика","Posts sent per day, the share delivered without errors, your posting streak, your busiest hour and your top hashtags. Honest numbers from your own deliveries.":"Постов в день, доля доставленных без ошибок, ваша серия публикаций, самый активный час и топ хештегов. Честные цифры по вашим собственным доставкам.","Content":"Контент","Library":"Библиотека","Pictures and files you uploaded for your posts, kept privately. Copy a link or delete what you no longer need. Every upload is checked before it can be published.":"Картинки и файлы, загруженные для постов, хранятся приватно. Скопируйте ссылку или удалите ненужное. Каждая загрузка проверяется до публикации.","Snippets":"Сниппеты","The texts you write again and again: a signature, a call to action, a block of hashtags. Save them once and insert one into the editor in a click.":"Тексты, которые вы пишете снова и снова: подпись, призыв к действию, блок хештегов. Сохраните один раз и вставляйте в редактор одним кликом.","Drafts":"Черновики","Park an unfinished post and come back to it. Vane keeps your last five drafts, and the text in the editor is also remembered in your browser while you type.":"Отложите недописанный пост и вернитесь к нему. Vane хранит ваши последние пять черновиков, а текст в редакторе ещё и запоминается в браузере, пока вы печатаете.","Assistants":"Помощники","Get help writing and posting":"Помощь в написании и публикации","Let AI polish the text, or hand the whole job to Claude.":"Пусть ИИ отполирует текст или отдайте всю работу Claude.","Assist":"Помощь","Vane AI":"Vane AI","Free on every plan: fix typos, add emoji and hashtags, keep the text inside each limit. With the AI Pass: change the tone, sharpen hooks and calls to action, write a version per network, turn an idea into a post.":"Бесплатно на каждом тарифе: исправление опечаток, эмодзи и хештеги, подгонка текста под лимит каждой сети. С AI Pass: смена тона, более цепкие хуки и призывы к действию, версия под каждую сеть, превращение идеи в пост.","Claude connector":"Коннектор Claude","Add Vane to Claude once, then post by talking: “post this to Telegram and Bluesky tomorrow at 9:00”. Ready-made commands cover posting, drafting, channels, what is scheduled and what went out.":"Добавьте Vane в Claude один раз и публикуйте разговором: «опубликуй это в Telegram и Bluesky завтра в 9:00». Готовые команды покрывают публикацию, черновики, каналы, что запланировано и что уже вышло.","Publish video the same way":"Публикуйте видео так же","A separate dashboard for video, on the same account. Coming soon: the video networks must approve Vane before it can go live.":"Отдельная панель для видео в том же аккаунте. Скоро: видеосети должны одобрить Vane, прежде чем он заработает.","Studio":"Studio","Soon":"Скоро","Upload and library":"Загрузка и библиотека","Upload large videos in resumable parts and keep them in a private library. The upload goes in parts, so a weak connection does not mean starting over.":"Загружайте большие видео возобновляемыми частями и храните их в приватной библиотеке. Загрузка идёт частями, поэтому слабое соединение не заставит начинать заново.","AI writer for video":"ИИ-автор для видео","Scripts with a hook, a body and a call to action for Shorts, TikTok, Reels and YouTube. Titles, descriptions, tags and YouTube chapters with timecodes.":"Сценарии с хуком, основной частью и призывом к действию для Shorts, TikTok, Reels и YouTube. Названия, описания, теги и главы YouTube с таймкодами.","Video channels and queue":"Видеоканалы и очередь","YouTube, TikTok and Instagram Reels, each one opening as the network approves Vane. The publishing queue behind them is already built.":"YouTube, TikTok и Instagram Reels, каждый открывается по мере одобрения Vane. Очередь публикации за ними уже готова.","Announce in your channels":"Анонс в ваших каналах","After an upload, send the news to your Vane Post channels in one click: the title, the start of the description, your tags and the link are already in the draft.":"После загрузки отправьте новость в каналы Vane Post в один клик: название, начало описания, ваши теги и ссылка уже в черновике.","Platform":"Платформа","Connect it to everything else":"Подключите ко всему остальному","One API sits under the dashboard, the Claude connector and your own tools.":"Один API лежит под панелью, коннектором Claude и вашими собственными инструментами.","API and keys":"API и ключи","Schedule and read posts from your own code. Test keys check everything without posting or counting. A retry key makes repeated requests safe, and an OpenAPI file describes every route.":"Планируйте и читайте посты из своего кода. Тестовые ключи проверяют всё без публикации и без учёта в квоте. Ключ повтора делает повторные запросы безопасными, а файл OpenAPI описывает каждый маршрут.","Webhooks":"Вебхуки","Get a signed message on your server when a post is published or fails. Vane retries on a schedule, from one minute up to twelve hours, and a slow receiver never delays your posts.":"Получайте подписанное сообщение на свой сервер, когда пост опубликован или не удался. Vane повторяет по расписанию, от одной минуты до двенадцати часов, а медленный получатель никогда не задерживает ваши посты.","Connectors":"Коннекторы","Claude, Notion, Make, Zapier, the WordPress and Obsidian plugins and the plain REST API work today; only a ChatGPT action is still to come. They all use the same keys and the same limits.":"Claude, Notion, Make, Zapier, плагины WordPress и Obsidian и обычный REST API работают уже сейчас; только действие для ChatGPT ещё впереди. Все они используют одни и те же ключи и лимиты.","Write faster. Sound right. Fit every network.":"Пишите быстрее. Звучите правильно. Подходите каждой сети.","Everyday polish is free on every plan. The heavier tools live in Vane AI Pass, which is included with Pro.":"Повседневная шлифовка бесплатна на любом тарифе. Более мощные инструменты — в Vane AI Pass, он входит в Pro.","Free AI utilities":"Бесплатные ИИ-утилиты","Every plan":"Любой тариф","Hashtag generator":"Генератор хештегов","Picks tags from the meaning of your post.":"Подбирает теги по смыслу поста.","Emoji and grammar fix":"Эмодзи и исправление грамматики","Basic text clean-up and a touch of emoji.":"Базовая чистка текста и немного эмодзи.","Character limit guard":"Контроль лимита символов","Adapts the length of your text to each network’s limit.":"Подгоняет длину текста под лимит каждой сети.","The free trial also includes 10 AI credits to try the heavier tools below.":"Бесплатный пробный период включает ещё 10 ИИ-кредитов, чтобы попробовать более мощные инструменты ниже.","Vane AI Pass":"Vane AI Pass","Included in Pro":"Входит в Pro","Smart re-formatter":"Умный переформатор","Turns a Telegram long-read into a thread for Threads and a post for LinkedIn.":"Превращает лонгрид из Telegram в тред для Threads и пост для LinkedIn.","Post and idea generator":"Генератор постов и идей","Drafts posts from scratch and builds a content plan.":"Пишет посты с нуля и строит контент-план.","Tone fixer":"Корректор тона","Switch between Professional, Viral, Friendly and Tech.":"Переключайтесь между «Профессионально», «Вирусно», «Дружелюбно» и «Технично».","Hook and CTA generator":"Генератор хуков и призывов","Sharper openings and clearer calls to action.":"Более цепкие начала и яснее призывы к действию.","Video script generator":"Генератор видеосценариев","Scripts and hooks for Shorts, TikTok and Reels. Arrives with Vane Studio.":"Сценарии и хуки для Shorts, TikTok и Reels. Появится вместе с Vane Studio.","Pro includes a soft limit of about":"В Pro действует мягкий лимит около","generations a month. On the Developer API plan, an AI post is":"генераций в месяц. На тарифе Developer API один ИИ-пост стоит","How the AI Pass works":"Как работает AI Pass","Eight tools for writing and fixing posts. Included in Pro. Free accounts get 10 credits to try.":"Восемь инструментов для написания и правки постов. Входят в Pro. Бесплатные аккаунты получают 10 кредитов на пробу.","Write from an idea, build on the posts that worked for you, plan seven posts for the week, or turn one article into a short series.":"Пишите с идеи, развивайте посты, которые у вас сработали, планируйте семь постов на неделю или превратите одну статью в короткую серию.","Improve":"Улучшение","Rewrite in another tone or in your own voice, get three openings and three endings, and make a version that fits each channel you picked.":"Перепишите в другом тоне или своим голосом, получите три начала и три концовки и сделайте версию под каждый выбранный канал.","Credits":"Кредиты","One use is one credit. Plan credits are spent first, then the AI Pass, then bonus credits. Paid extras happen only if you switch them on. Otherwise a request over the limit is refused and nothing is charged.":"Одно использование — один кредит. Сначала тратятся кредиты тарифа, затем AI Pass, затем бонусные. Платные дополнения включаются только если вы их включите. Иначе запрос сверх лимита отклоняется, и ничего не списывается.","Headless and API-first.":"Headless и API-first.","Everything the dashboard does is one REST call away. Plug Vane into your scripts, your no-code automations or your favourite AI assistant.":"Всё, что делает панель, — один REST-вызов. Подключите Vane к своим скриптам, no-code автоматизациям или любимому ИИ-ассистенту.","API preview":"Пример API","# Schedule a post to your channels":"# Запланировать пост в ваши каналы","# Response":"# Ответ","Works with your stack":"Работает с вашим стеком","REST API":"REST API","Bearer auth, webhooks and an OpenAPI spec.":"Bearer-авторизация, вебхуки и спецификация OpenAPI.","Live":"Работает","Make.com and Zapier":"Make.com и Zapier","Custom GPT action":"Действие для Custom GPT","Claude and Notion (MCP)":"Claude и Notion (MCP)","Keys built for safety":"Ключи, созданные для безопасности","Separate keys for text and video, each limited to its own endpoints.":"Отдельные ключи для текста и видео, каждый ограничен своими эндпоинтами.","Test keys simulate responses without posting or touching your quota.":"Тестовые ключи имитируют ответы без публикации и без расхода квоты.","Keys are hashed with SHA-256 before they are stored.":"Ключи хранятся в виде хешей SHA-256.","Pro Dashboard":"Pro Dashboard","When it matters, Vane goes first.":"Когда это важно, Vane идёт первым.","Two things that only the paid dashboard plans have: your posts get a lane of their own and leave on the second you chose, and your AI assistant gets a bigger toolbox than “send this text”.":"Две вещи, которые есть только на платных тарифах с панелью: ваши посты получают отдельную полосу и уходят в выбранную секунду, а ваш ИИ-ассистент получает набор инструментов побольше, чем «отправь этот текст».","Priority dispatch":"Приоритетная отправка","Free Trial posts share one queue and go out at the next whole minute, in order. Pro posts are taken from their own lane, ahead of that queue, and sent on the second you picked. Set an announcement for 09:00:30 and it leaves at 09:00:30, not at 09:01.":"Посты Free Trial делят одну очередь и уходят в ближайшую целую минуту по порядку. Посты Pro берутся из своей полосы, впереди этой очереди, и отправляются в выбранную секунду. Поставьте анонс на 09:00:30 — он уйдёт в 09:00:30, а не в 09:01.","A post scheduled for 09:00:30 leaves at 09:01:00 on the Free Trial and at 09:00:30 on Pro":"Пост, запланированный на 09:00:30, уходит в 09:01:00 на Free Trial и в 09:00:30 на Pro","Scheduled for 09:00:30":"Запланировано на 09:00:30","Free Trial · shared queue":"Free Trial · общая очередь","leaves 09:01:00":"уходит в 09:01:00","Pro · priority lane":"Pro · приоритетная полоса","leaves 09:00:30":"уходит в 09:00:30","Its own lane: a rush of free posts never makes a Pro post wait.":"Своя полоса: наплыв бесплатных постов никогда не заставит Pro-пост ждать.","Sent on your second, give or take the moment the network takes to answer.":"Отправка в вашу секунду, плюс-минус время, которое сети нужно на ответ.","Cancel right up to the last second: a post is only picked up when its time comes.":"Отменяйте до последней секунды: пост берётся в работу только тогда, когда придёт его время.","Honest fine print: it is on-the-second, not on-the-millisecond. A post made less than a minute ahead (“post now”) goes out at the next run, first in line.":"Честная оговорка: это точность до секунды, а не до миллисекунды. Пост, созданный меньше чем за минуту («опубликовать сейчас»), уходит при ближайшем запуске, первым в очереди.","Agent tools for Claude and Notion":"Инструменты агента для Claude и Notion","The basics (list channels, list posts, schedule a post) are free. On Pro your assistant gets four more tools, so it can read your numbers, pick the times, write in your voice and schedule a whole series in one call.":"Базовые (список каналов, список постов, запланировать пост) бесплатны. На Pro ваш ассистент получает ещё четыре инструмента: читать ваши цифры, подбирать время, писать вашим голосом и планировать целую серию одним вызовом.","MCP tools":"Инструменты MCP","# Free Trial and up":"# Free Trial и выше","# Pro adds":"# Pro добавляет","what worked, from your results":"что сработало, по вашим результатам","the best free slots this week":"лучшие свободные слоты на этой неделе","how you sound":"как вы звучите","up to 14 posts in one call":"до 14 постов за один вызов","“Plan five posts about Friday’s launch, in my voice, on my best times. Show me first.”":"«Запланируй пять постов о пятничном запуске, моим голосом, на лучшее время. Сначала покажи мне».","Your assistant writes, Vane schedules. These tools do arithmetic on your own data and spend no AI credits.":"Ассистент пишет, Vane планирует. Эти инструменты считают по вашим данным и не тратят ИИ-кредиты.","Nothing goes out without your yes: a series has a dry run first, and a retry never posts twice.":"Ничего не уходит без вашего «да»: у серии сначала пробный прогон, а повтор никогда не публикует дважды.","Several assistants at once, each with its own key: up to 10 on Pro, 3 on the Free Trial.":"Несколько ассистентов одновременно, у каждого свой ключ: до 10 на Pro, 3 на Free Trial.","How it works":"Как это работает","Three steps. That’s the whole product.":"Три шага. Это весь продукт.","Write":"Пишите","Type or paste your post, or let Vane AI draft and reformat it. Attach media. One draft, every network.":"Введите или вставьте пост либо поручите Vane AI составить и переформатировать его. Прикрепите медиа. Один черновик — все сети.","Pick networks":"Выберите сети","Choose one channel or all of them. Preview how the post looks on each before you commit.":"Выберите один канал или все. Посмотрите, как пост выглядит в каждом, прежде чем подтвердить.","Publish":"Публикуйте","Choose when it goes out. The edge publisher sends it on the minute and logs the result for every channel.":"Выберите, когда отправить. Edge-публикатор отправит ровно в минуту и запишет результат по каждому каналу.","Simple plans. Do the math yourself.":"Простые тарифы. Посчитайте сами.","Start free, no card required. Pay a flat monthly price when you are ready. No per-channel fees on any plan.":"Начните бесплатно, без карты. Платите фиксированную цену в месяц, когда будете готовы. Без платы за канал на любом тарифе.","Free Trial":"Free Trial","No card required.":"Без карты.","30 posts in total":"30 постов всего","Up to 2 connected channels":"До 2 подключённых каналов","10 free AI credits":"10 бесплатных ИИ-кредитов","Try the dashboard and the API":"Попробуйте панель и API","Developer API":"Developer API","/ month":"/ месяц","A headless gateway for scripts and bots.":"Headless-шлюз для скриптов и ботов.","REST API with Bearer auth, webhooks and an OpenAPI spec":"REST API с Bearer-авторизацией, вебхуками и спецификацией OpenAPI","180 API posts a month (about 6 a day)":"180 API-постов в месяц (около 6 в день)","Claude and Notion (MCP) access today, Custom GPT when it launches":"Доступ для Claude и Notion (MCP) уже сейчас, Custom GPT — после запуска","Extra posts: $0.03 each, $0.09 for AI posts":"Дополнительные посты: $0.03 за пост, $0.09 за ИИ-пост","Early Bird":"Early Bird","standard, or $120 a year.":"обычная цена, или $120 в год.","Full dashboard with calendar and Kanban":"Полная панель с календарём и Kanban","Unlimited workspaces and channels":"Неограниченно рабочих пространств и каналов","1,000 posts a month":"1 000 постов в месяц","Telegram inline buttons, spoilers and polls":"Inline-кнопки, спойлеры и опросы в Telegram","Media library on Cloudflare R2":"Медиатека на Cloudflare R2","Vane AI Pass included":"Vane AI Pass включён","Priority dispatch: posts leave on the second you chose":"Приоритетная отправка: посты уходят в выбранную вами секунду","Advanced MCP tools for Claude and Notion":"Расширенные инструменты MCP для Claude и Notion","Extra posts: $0.015 each, $0.045 for AI posts":"Дополнительные посты: $0.015 за пост, $0.045 за ИИ-пост","Video publishing, end to end.":"Публикация видео от начала до конца.","YouTube Shorts, TikTok and Instagram Reels":"YouTube Shorts, TikTok и Instagram Reels","YouTube long-form with custom thumbnails, playlists and tags":"Длинные ролики YouTube с собственными обложками, плейлистами и тегами","Resumable uploads on Cloudflare R2":"Возобновляемая загрузка на Cloudflare R2","AI hooks, scripts, descriptions, tags and timestamps":"ИИ-хуки, сценарии, описания, теги и таймкоды","Need the dashboard and the API?":"Нужны и панель, и API?","Add the API to Pro for":"Добавьте API к Pro за","+$4.99 a month":"+$4.99 в месяц",". It adds 180 API posts and keeps Pro’s low overage rates.":". Он добавляет 180 API-постов и сохраняет низкие тарифы Pro на превышение.","Going over your quota":"Превышение квоты","Posts beyond your monthly quota are billed per post. Pro gets half the Developer API rate.":"Посты сверх месячной квоты оплачиваются за штуку. У Pro — половина тарифа Developer API.","Plan":"Тариф","Post":"Пост","AI post":"ИИ-пост","Simple payment":"Простая оплата","Your plan switches on automatically the moment the payment clears.":"Ваш тариф включается автоматически, как только платёж пройдёт.","Savings calculator":"Калькулятор экономии","Enter what a per-channel tool charges you and how many channels you run. Vane Pro is compared at its":"Введите, сколько вы платите инструменту с оплатой за канал и сколько у вас каналов. Vane Pro сравнивается по","standard price, so Early Bird saves you even more. The figure below is illustrative; use your own numbers.":"обычной цене, так что с Early Bird вы сэкономите ещё больше. Цифра ниже — иллюстрация; подставьте свои числа.","Price per channel elsewhere ($/mo)":"Цена за канал в другом сервисе ($/мес)","Per-channel pricing":"Оплата за канал","Vane Pro":"Vane Pro","FAQ":"FAQ","Questions, answered.":"Вопросы и ответы.","Is the price really flat?":"Цена действительно фиксированная?","Yes. Pro is":"Да. Pro стоит","a month (Early Bird) or":"в месяц (Early Bird) или","standard, or":"обычная цена, или","a year, and it covers unlimited channels and workspaces. There are no per-channel add-ons. Only posts beyond your monthly quota are billed, at the overage rates in the pricing section.":"в год, и включает неограниченно каналов и рабочих пространств. Платных дополнений за канал нет. Оплачиваются только посты сверх месячной квоты, по тарифам на превышение из раздела цен.","Do I need a card to try Vane?":"Нужна ли карта, чтобы попробовать Vane?","No. The Free Trial needs no card and includes 30 posts in total, up to 2 channels and 10 AI credits. When the 30 posts are used, publishing stops until you choose a plan. We never charge you automatically.":"Нет. Free Trial не требует карты и включает 30 постов всего, до 2 каналов и 10 ИИ-кредитов. Когда 30 постов израсходованы, публикация останавливается, пока вы не выберете тариф. Мы никогда не списываем деньги автоматически.","What happens if I go over my monthly quota?":"Что будет, если я превышу месячную квоту?","Extra posts are billed per post. On Pro that is":"Дополнительные посты оплачиваются за штуку. На Pro это","per post and":"за пост и","per AI-generated post. On the Developer API plan it is":"за пост, сгенерированный ИИ. На тарифе Developer API это","and":"и",". Pro includes":". Pro включает","posts a month and the Developer API includes":"постов в месяц, а Developer API включает","Which networks are supported?":"Какие сети поддерживаются?","Telegram, Bluesky, Mastodon, Discord and Dev.to work today; LinkedIn, Threads, Reddit and Facebook Pages open as each network approves Vane. Each one gets its own preview and its own character limit (Telegram 4,096, Mastodon 500, Bluesky 300), so you see what fits before you schedule.":"Telegram, Bluesky, Mastodon, Discord и Dev.to работают уже сейчас; LinkedIn, Threads, Reddit и страницы Facebook откроются по мере одобрения Vane. У каждой свой превью и свой лимит символов (Telegram 4 096, Mastodon 500, Bluesky 300), так что вы видите, что поместится, до планирования.","What is Vane AI Pass?":"Что такое Vane AI Pass?","A set of AI tools included with Pro: a re-formatter that turns Telegram long-reads into threads and LinkedIn posts, a post and idea generator, a tone fixer, and a hook and CTA generator. Pro has a soft limit of about":"Набор ИИ-инструментов, входящий в Pro: переформатор, превращающий лонгриды Telegram в треды и посты LinkedIn, генератор постов и идей, корректор тона и генератор хуков и призывов. В Pro действует мягкий лимит около","generations a month. Hashtags, emoji and grammar fixes and the character limit guard are free on every plan.":"генераций в месяц. Хештеги, эмодзи, исправление грамматики и контроль лимита символов бесплатны на любом тарифе.","What is priority dispatch?":"Что такое приоритетная отправка?","On the paid dashboard plans (Pro and the Suite) your scheduled posts are picked up from a lane of their own, ahead of the shared queue, and sent on the second you chose instead of the next whole minute. A rush of Free Trial posts can never make a Pro post wait. It is on-the-second, not on-the-millisecond: the network still takes a moment to answer, and a post made less than a minute ahead goes out at the next run, first in line. You can still cancel it until its time comes.":"На платных тарифах с панелью (Pro и Suite) ваши запланированные посты берутся из отдельной полосы, впереди общей очереди, и отправляются в выбранную вами секунду, а не в ближайшую целую минуту. Наплыв постов Free Trial никогда не заставит Pro-пост ждать. Это точность до секунды, а не до миллисекунды: сети всё равно нужно время на ответ, а пост, созданный меньше чем за минуту, уходит при ближайшем запуске, первым в очереди. Отменить его можно, пока не наступило его время.","What do the advanced MCP tools add?":"Что добавляют расширенные инструменты MCP?","Every plan lets Claude or a Notion agent list your channels and posts and schedule a post. On Pro and the Suite the assistant also gets four tools: one that reads how your own posts did (best and weakest posts, patterns by day, time, length and media), one that finds the best free time slots, one that returns your saved tone of voice, and one that schedules up to 14 posts in a single call, with a dry run first. The assistant does the writing and the thinking; the tools only read your data and use the calendar, so they spend no AI credits.":"На любом тарифе Claude или агент Notion может показать ваши каналы и посты и запланировать пост. На Pro и Suite ассистент получает ещё четыре инструмента: один читает, как сработали ваши посты (лучшие и слабейшие, закономерности по дню, времени, длине и медиа), второй находит лучшие свободные слоты, третий возвращает ваш сохранённый тон голоса, четвёртый планирует до 14 постов за один вызов, сначала с пробным прогоном. Писать и думать будет ассистент; инструменты только читают ваши данные и пользуются календарём, поэтому не тратят ИИ-кредиты.","Can I use Vane from code or no-code tools?":"Можно ли пользоваться Vane из кода или no-code инструментов?","Yes. The REST API comes with the Developer plan or as a +":"Да. REST API идёт с тарифом Developer или как дополнение +","add-on to Pro. Claude, Notion, Make.com, Zapier, the WordPress plugin and the Obsidian plugin work today; only a Custom GPT action is still to come.":"к Pro. Claude, Notion, Make.com, Zapier, плагин WordPress и плагин Obsidian работают уже сейчас; только действие Custom GPT ещё впереди.","When will video publishing arrive?":"Когда появится публикация видео?","Vane Studio (":"Vane Studio (","a month) is the next expansion, covering YouTube Shorts, TikTok, Instagram Reels and YouTube long-form. It needs approval from each platform before it can go live, so we will announce the date once those clear. Join the waitlist and we will tell you.":"в месяц) — следующее расширение: YouTube Shorts, TikTok, Instagram Reels и длинные ролики YouTube. Для запуска нужно одобрение каждой платформы, поэтому мы объявим дату, когда они его дадут. Вступайте в список ожидания, и мы вам сообщим.","How do I pay?":"Как оплатить?","Online, on the payment provider's secure page. Your plan or API key switches on automatically as soon as the payment is confirmed.":"Онлайн, на защищённой странице платёжного провайдера. Ваш тариф или API-ключ включается автоматически, как только платёж подтверждён.","How accurate is the scheduling?":"Насколько точно работает планирование?","Posts are scheduled to the minute. A scheduler on Cloudflare’s edge checks for due posts every minute and sends them straight away, so there is no extra queue delay on our side. Each platform’s own API response time still applies.":"Посты планируются с точностью до минуты. Планировщик на edge Cloudflare проверяет посты к отправке каждую минуту и сразу их отправляет, так что с нашей стороны нет дополнительной задержки очереди. Время ответа API каждой платформы по-прежнему учитывается.","When does Vane launch?":"Когда запустится Vane?","We are onboarding people from the waitlist first. Join with your email and we will write to you when your spot opens.":"Сначала мы подключаем людей из списка ожидания. Вступайте со своей почтой, и мы напишем, когда подойдёт ваша очередь.","What happens to my email?":"Что будет с моей почтой?","It is stored in our database and used only to tell you about Vane’s launch. We don’t sell or share it.":"Она хранится в нашей базе и используется только для сообщения о запуске Vane. Мы не продаём её и не передаём.","Are the demos above real?":"Демо выше настоящие?","Both are simulations that run in your browser. The post preview and the iPad video demo do not publish anywhere, and nothing you type is sent to a server.":"Оба — симуляции, которые работают в вашем браузере. Превью поста и видеодемо на iPad нигде не публикуют, и ничего из того, что вы вводите, не отправляется на сервер.","Follow":"Подписаться","Follow Vane where you already are.":"Подписывайтесь на Vane там, где вы уже есть.","Product news, releases and tips, posted to the networks you use every day.":"Новости продукта, релизы и советы, публикуются в сетях, которыми вы пользуетесь каждый день.","Telegram":"Telegram","News and releases from Vane.":"Новости и релизы Vane.","Bluesky":"Bluesky","Product updates and tips.":"Обновления продукта и советы.","Mastodon":"Mastodon","Updates for the fediverse.":"Обновления для федиверса.","Partner":"Партнёр","Built with WYSB.":"Сделано с WYSB.","WYSB is a web studio that designs and builds websites, online stores and web apps, and a partner that helped build Vane. Meet them, and see what the partnership means.":"WYSB — веб-студия, которая проектирует и создаёт сайты, интернет-магазины и веб-приложения, и партнёр, помогавший строить Vane. Познакомьтесь с ними и узнайте, что значит это партнёрство.","Visit wysb.eu ↗":"Перейти на wysb.eu ↗","About the partnership":"О партнёрстве","WYSB, Vane's partner":"@WYSB, партнёр Vane","Stop paying per channel.":"Хватит платить за каждый канал.","Join the waitlist for early access. Pro starts at":"Вступайте в список ожидания и получите ранний доступ. Pro стоит от","a month, flat, with every channel included.":"в месяц, фиксированно, со всеми каналами.","Email":"Почта","Type your email":"Введите вашу почту","Product":"Продукт","Changelog":"Список изменений","API":"API","OpenAPI spec":"Спецификация OpenAPI","Security":"Безопасность","Company":"Компания","About":"О нас","Contact":"Контакты","Legal":"Правовая информация","Privacy":"Конфиденциальность","Terms":"Условия","Data deletion":"Удаление данных","Vane · vaneapp.dev · Built with":"Vane · vaneapp.dev · Сделано с","Can’t reach Vane":"Нет связи с Vane","Dashboard":"Панель","Open dashboard":"Открыть панель","Joining…":"Отправляем…","Please enter a valid email address.":"Введите корректный адрес почты.","You are already on the list. We will be in touch.":"Вы уже в списке. Мы свяжемся с вами.","You are in! We will email you when your spot opens.":"Вы в списке! Мы напишем, когда подойдёт ваша очередь.","Something went wrong. Please try again.":"Что-то пошло не так. Попробуйте ещё раз.","Network error. Check your connection and try again.":"Ошибка сети. Проверьте соединение и попробуйте ещё раз.","Pick a network to see how your post will look.":"Выберите сеть, чтобы увидеть, как будет выглядеть пост.","Write something first.":"Сначала что-нибудь напишите.","Pick at least one network.":"Выберите хотя бы одну сеть.","Scheduling…":"Планируем…","Scheduled":"Запланировано","Edit post":"Изменить пост","All delivered (simulated).":"Всё доставлено (симуляция).","Uploading…":"Загружаем…","Demo limit reached":"Лимит демо достигнут","Type a video title first.":"Сначала введите название видео.","✓ Published":"✓ Опубликовано","That is all three. Reset the demo to try again.":"Это все три. Сбросьте демо, чтобы попробовать снова.","Published to your channel.":"Опубликовано в вашем канале.","Enter a per-channel price to compare.":"Введите цену за канал для сравнения.","You would save":"Вы сэкономите","a month,":"в месяц,","a year.":"в год.","In 1 minute":"Через 1 минуту","Tomorrow · 09:00":"Завтра · 09:00","Friday · 18:30":"Пятница · 18:30","Most popular":"Популярный","one-time":"разово","month":"месяц","year":"год"};
var KEY = 'vane_lang';
var TITLE_EN = document.title;
var TITLE_RU = 'Vane — Пишите один раз. Публикуйте везде.';
var ATTRS = ['placeholder', 'aria-label', 'alt', 'title'];
var SKIP = { SCRIPT: 1, STYLE: 1, SVG: 1, NOSCRIPT: 1, TEXTAREA: 1, CODE: 1, PRE: 1 };
var AGO = { week: ['нед.', 'нед.'], weeks: ['нед.', 'нед.'], month: ['мес.', 'мес.'], months: ['мес.', 'мес.'], day: ['дн.', 'дн.'], days: ['дн.', 'дн.'], year: ['г.', 'г.'], years: ['г.', 'г.'] };
var PATTERNS = [
  [/^(\d+) characters$/, function (m) { return m[1] + ' символов'; }],
  [/^Queued for (.+) on (\d+) networks?$/, function (m) { return 'В очереди: ' + (DICT[m[1]] || m[1]) + ', сетей: ' + m[2]; }],
  [/^» fast-forwarding to (\d\d:\d\d):00 …$/, function (m) { return '» перематываем до ' + m[1] + ':00 …'; }],
  [/^delivered at (\d\d:\d\d):00 · (\d+) ms$/, function (m) { return 'доставлено в ' + m[1] + ':00 · ' + m[2] + ' мс'; }],
  [/^(\d+) \/ (\d+) uploads$/, function (m) { return m[1] + ' / ' + m[2] + ' загрузок'; }],
  [/^At this setup per-channel pricing is cheaper\. Vane wins from (\d+) channels up\.$/, function (m) { return 'При таких данных оплата за канал дешевле. Vane выигрывает от ' + m[1] + ' каналов.'; }],
  [/^(Your Channel · )?([\d.]+K) views · (\d+) (\w+) ago$/, function (m) { var u = AGO[m[4]]; return (m[1] ? 'Ваш канал · ' : '') + m[2] + ' просмотров · ' + m[3] + ' ' + (u ? u[0] : m[4]) + ' назад'; }],
  [/^Your Channel · 0 views · Just now$/, function () { return 'Ваш канал · 0 просмотров · только что'; }]
];

var lang = 'en';
var nodes = new Map();
var attrs = new Map();
var observer = null;

function norm(s) { return s.replace(/\s+/g, ' ').trim(); }

function translate(text) {
  var key = norm(text);
  if (!key) return null;
  if (Object.prototype.hasOwnProperty.call(DICT, key)) return DICT[key];
  for (var i = 0; i < PATTERNS.length; i++) {
    var m = PATTERNS[i][0].exec(key);
    if (m) return PATTERNS[i][1](m);
  }
  return null;
}

function skipped(el) {
  for (var e = el; e && e.nodeType === 1; e = e.parentNode) {
    if (SKIP[e.nodeName.toUpperCase()] || e.hasAttribute('data-no-i18n')) return true;
  }
  return false;
}

function doText(node) {
  var known = nodes.get(node);
  if (known && node.data === known.ru) return;
  if (skipped(node.parentNode)) return;
  var ru = translate(node.data);
  if (ru === null) { nodes.delete(node); return; }
  var lead = /^\s*/.exec(node.data)[0];
  var tail = /\s*$/.exec(node.data)[0];
  var out = lead + ru + tail;
  nodes.set(node, { en: node.data, ru: out });
  node.data = out;
}

function doAttrs(el) {
  if (skipped(el)) return;
  ATTRS.forEach(function (a) {
    var v = el.getAttribute(a);
    if (!v) return;
    var rec = attrs.get(el) || {};
    if (rec[a] && rec[a].ru === v) return;
    var ru = translate(v);
    if (ru === null) return;
    rec[a] = { en: v, ru: ru };
    attrs.set(el, rec);
    el.setAttribute(a, ru);
  });
}

function walk(root) {
  if (root.nodeType === 3) { doText(root); return; }
  if (root.nodeType !== 1 || skipped(root)) return;
  doAttrs(root);
  var tw = document.createTreeWalker(root, NodeFilter.SHOW_TEXT | NodeFilter.SHOW_ELEMENT, {
    acceptNode: function (n) { return n.nodeType === 1 && skipped(n) ? NodeFilter.FILTER_REJECT : NodeFilter.FILTER_ACCEPT; }
  });
  var n;
  while ((n = tw.nextNode())) { if (n.nodeType === 3) doText(n); else doAttrs(n); }
}

function restore() {
  nodes.forEach(function (rec, node) { if (node.data === rec.ru) node.data = rec.en; });
  attrs.forEach(function (rec, el) {
    Object.keys(rec).forEach(function (a) { if (el.getAttribute(a) === rec[a].ru) el.setAttribute(a, rec[a].en); });
  });
  nodes.clear();
  attrs.clear();
}

function watch(on) {
  if (!on) { if (observer) observer.disconnect(); observer = null; return; }
  if (observer) return;
  observer = new MutationObserver(function (list) {
    list.forEach(function (m) {
      if (m.type === 'characterData') doText(m.target);
      else if (m.type === 'attributes') doAttrs(m.target);
      else m.addedNodes.forEach(walk);
    });
  });
  observer.observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ATTRS });
}

function paint() {
  document.querySelectorAll('[data-lang]').forEach(function (b) {
    var on = b.getAttribute('data-lang') === lang;
    b.setAttribute('aria-pressed', String(on));
    b.style.color = on ? '#fff' : '';
  });
}

function set(next, save) {
  if (next !== 'ru') next = 'en';
  if (next === lang && observer === null && next === 'en') { paint(); return; }
  watch(false);
  restore();
  lang = next;
  document.documentElement.lang = lang;
  document.title = lang === 'ru' ? TITLE_RU : TITLE_EN;
  if (lang === 'ru') { walk(document.body); watch(true); }
  paint();
  if (save) { try { localStorage.setItem(KEY, lang); } catch (e) { /* private mode */ } }
}

function start() {
  var want = 'en';
  try { want = new URLSearchParams(location.search).get('lang') || localStorage.getItem(KEY) || 'en'; } catch (e) { /* private mode */ }
  document.addEventListener('click', function (e) {
    var b = e.target.closest && e.target.closest('[data-lang]');
    if (b) set(b.getAttribute('data-lang'), true);
  });
  set(want === 'ru' ? 'ru' : 'en', false);
}

if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', start); else start();
})();
